package jsonschema

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/stubbedev/maestro/internal/json/res"
	"github.com/stubbedev/maestro/internal/php"
	"github.com/stubbedev/maestro/internal/testutil"
)

// oracleCase is a record of testdata/oracle/schema.json.gz (generated by
// tools/oracle/json/schema.php).
type oracleCase struct {
	Schema string          `json:"schema"`
	Doc    string          `json:"doc"`
	Errors [][]any         `json:"errors"`
	E      *string         `json:"e"`
	JSON   json.RawMessage `json:"jsonfile"`
}

func loadOracle(t testing.TB) []oracleCase {
	t.Helper()
	data, err := testutil.ReadGoldenFile("testdata/oracle/schema.json.gz")
	if err != nil {
		t.Fatal(err)
	}
	var cases []oracleCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
	}

	return cases
}

const draft04 = "https://json-schema.org/draft-04/schema#"

// oracleSchema builds the schema objects the generator validates against,
// as JsonFile::validateJsonSchema does.
func oracleSchema(kind string) any {
	ref := func(uri string) *php.Object {
		o := php.NewObject()
		o.Set("$ref", uri)
		o.Set("$schema", draft04)
		return o
	}
	switch kind {
	case "composer":
		return ref(res.ComposerSchemaURI)
	case "lock":
		return ref(res.LockSchemaURI)
	case "auth":
		return ref(res.ComposerSchemaURI + "#/properties/config")
	case "repository":
		return ref(res.RepositorySchemaURI)
	}
	s, _ := php.JSONDecode(res.ComposerSchema(), false)
	o := s.(*php.Object)
	o.Set("additionalProperties", false)
	o.Set("required", php.ListOf("name", "description"))

	return o
}

func TestSchemaOracle_Validator(t *testing.T) {
	cases := loadOracle(t)
	failures := 0
	for _, c := range cases {
		data, err := php.JSONDecode(c.Doc, false)
		if err != nil {
			t.Fatalf("%s: %v", c.Doc, err)
		}
		errs, err := NewValidator(resRetriever).Validate(data, oracleSchema(c.Schema))
		if !sameResult(c, errs, err) {
			failures++
			if failures <= 20 {
				t.Errorf("%s %s:\n got %v %s\nwant %v %v", c.Schema, c.Doc, err, formatErrors(errs), c.E, c.Errors)
			}
		}
	}
	if failures > 0 {
		t.Errorf("%d of %d cases differ", failures, len(cases))
	}
}

func formatErrors(errs []Error) string {
	var out []any
	for _, e := range errs {
		out = append(out, []any{e.Property, e.Pointer, e.Message, e.Constraint.Name, php.VarExport(e.Constraint.Params), e.Context})
	}
	b, _ := json.Marshal(out)

	return string(b)
}

func BenchmarkValidateComposerJSON(b *testing.B) {
	data, _ := os.ReadFile("../../../.ref/composer/composer.json")
	if data == nil {
		b.Skip("no .ref")
	}
	doc, _ := php.JSONDecode(string(data), false)
	schema := oracleSchema("composer")
	b.ReportAllocs()
	for b.Loop() {
		if _, err := NewValidator(resRetriever).Validate(doc, schema); err != nil {
			b.Fatal(err)
		}
	}
}

// TestSchemaOracle_Generic compares Validate with the PHP validator for the
// hand-written schemas of tools/oracle/json/schema_generic.php.
func TestSchemaOracle_Generic(t *testing.T) {
	data, err := testutil.ReadGoldenFile("testdata/oracle/generic.json.gz")
	if err != nil {
		t.Fatal(err)
	}
	var cases []oracleCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
	}
	failures := 0
	for _, c := range cases {
		doc, _ := php.JSONDecode(c.Doc, false)
		schema, _ := php.JSONDecode(c.Schema, false)
		errs, err := NewValidator(resRetriever).Validate(doc, schema)
		if !sameResult(c, errs, err) {
			failures++
			if failures <= 30 {
				t.Errorf("%s %s:\n got %v %s\nwant %v %v", c.Schema, c.Doc, err, formatErrors(errs), derefString(c.E), c.Errors)
			}
		}
	}
	if failures > 0 {
		t.Errorf("%d of %d cases differ", failures, len(cases))
	}
}

func derefString(s *string) string {
	if s == nil {
		return "<nil>"
	}

	return *s
}

func sameResult(c oracleCase, errs []Error, err error) bool {
	switch {
	case c.E != nil:
		return err != nil && err.Error() == *c.E
	case err != nil, len(errs) != len(c.Errors):
		return false
	}
	for i, e := range c.Errors {
		g := errs[i]
		if g.Property != e[0] || g.Pointer != e[1] || g.Message != e[2] || g.Constraint.Name != e[3] ||
			php.VarExport(g.Constraint.Params) != e[4] || float64(g.Context) != e[5] {
			return false
		}
	}

	return true
}
